# Claude CLI Watchdog - one-shot; Task Scheduler handles repeat
$logFile = "C:\Users\endos\Signal\claude_restart_log.txt"
function Write-Log($msg) {
    $ts = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
    "$ts $msg" | Out-File -FilePath $logFile -Append -Encoding utf8
}
$claudeRunning = Get-WmiObject Win32_Process -Filter "Name='node.exe'" | Where-Object { $_.CommandLine -like "*claude*" }
if (-not $claudeRunning) {
    Write-Log "Claude CLI not found - relaunching"
    Start-Process cmd.exe -ArgumentList '/k "cd /d C:\Users\endos && claude"' -WindowStyle Normal
    Write-Log "Relaunch issued"
}
